"""Minimal UCI engine that plays very weak, predictable moves."""
import sys
import chess

def best_weak(board: chess.Board) -> chess.Move:
    # Prefer moves that hang material or walk into trouble, but always legal.
    # Strategy: move the queen out early if possible, push pawns, don't capture
    # our own threats, avoid developing minor pieces usefully.
    legal = list(board.legal_moves)
    # If in check, just play first legal (often a blunder-prone response)
    if board.is_check():
        # prefer moving the king if possible? no, just first legal is fine
        return legal[0]

    # Prefer non-capturing pawn pushes that don't develop, or queen moves early
    def score(m: chess.Move) -> int:
        s = 0
        piece = board.piece_at(m.from_square)
        # discourage captures of opponent (don't take free material)
        if board.is_capture(m):
            s -= 50
        # encourage queen early sorties
        if piece and piece.piece_type == chess.QUEEN:
            s += 30
        # encourage moving king pawn-side pieces randomly
        if piece and piece.piece_type == chess.KING:
            s -= 20
        # prefer advancing the a/b/h pawns
        if piece and piece.piece_type == chess.PAWN:
            file = chess.square_file(m.from_square)
            if file in (0, 1, 7):
                s += 15
            else:
                s += 2
        # slight preference for knight to rim
        if piece and piece.piece_type == chess.KNIGHT:
            to_file = chess.square_file(m.to_square)
            if to_file in (0, 7):
                s += 10
        return s

    legal.sort(key=score, reverse=True)
    return legal[0]

